  // Helper methods attached non-enumerably so Object.keys(PORTHOLE_BRANCH_TREES) === ["1".."55"]
  function resolveShowcaseAt(portalId, tSec) {
    var tree = PORTHOLE_BRANCH_TREES[portalId];
    if (!tree || !tree.showcaseScript) return null;
    var dur = tree.showcaseScript.duration || 18.0;
    var t = Math.max(0, Math.min(dur - 0.0001, Number(tSec) || 0));
    var segs = tree.showcaseScript.segments;
    for (var i = 0; i < segs.length; i++) {
      var s = segs[i];
      if (t >= s.start && (t < s.end || i === segs.length - 1)) {
        var localT = t - s.start;
        var segDur = Math.max(0.001, s.end - s.start);
        var phase = s.phase;
        var tier = s.tier;
        if (s.key === "finale_triangle_preposterous" && t < (s.stemEnd || 14.85)) {
          phase = "stem";
          tier = null;
        }
        return {
          t: t,
          segmentIndex: s.index,
          segmentKey: s.key,
          phase: phase,
          button: s.button,
          tier: tier,
          isRewinding: !!(s.rewindEnd && t < s.rewindEnd),
          snailMail: !!s.snailMail,
          alienFinale: !!(s.alienFinale && phase === "outcome"),
          localT: Number(localT.toFixed(4)),
          progress: Number((localT / segDur).toFixed(4)),
          segment: s
        };
      }
    }
    return null;
  }

